/* ---- letters: stretch each glyph's exact ink box to fill its cell (zero gaps) ---- */
var FONT = '500 100px "Manrope", sans-serif';
var OX = 90, OY = 220, CW = 360, CH = 360;

function inkViewBox(letter){
  var c = document.createElement('canvas');
  c.width = CW; c.height = CH;
  var ctx = c.getContext('2d');
  ctx.font = FONT; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillStyle = '#fff';
  ctx.fillText(letter, OX, OY);
  var d = ctx.getImageData(0, 0, CW, CH).data;
  var minX = CW, minY = CH, maxX = -1, maxY = -1;
  for (var y = 0; y < CH; y++){
    var row = y * CW * 4;
    for (var x = 0; x < CW; x++){
      if (d[row + x * 4 + 3] > 16){
        if (x < minX) minX = x; if (x > maxX) maxX = x;
        if (y < minY) minY = y; if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < 0) return null;
  return (minX - OX) + ' ' + (minY - OY) + ' ' + (maxX - minX + 1) + ' ' + (maxY - minY + 1);
}

function fitGlyphs(){
  document.querySelectorAll('.glyph').forEach(function(svg){
    var vb = inkViewBox(svg.querySelector('text').textContent);
    if (vb){ svg.setAttribute('viewBox', vb); svg.setAttribute('preserveAspectRatio', 'none'); }
  });
}

/* ---- junction highlights: a white square at every grid-line intersection ---- */
function placeNodes(){
  var logo = document.querySelector('.logo');
  logo.querySelectorAll('.node').forEach(function(n){ n.remove(); });
  var lr = logo.getBoundingClientRect();
  var seen = {};
  function addNode(px, py){
    var x = Math.round(px - lr.left - logo.clientLeft);
    var y = Math.round(py - lr.top  - logo.clientTop);
    var key = x + ',' + y;
    if (seen[key]) return;
    seen[key] = 1;
    var n = document.createElement('div');
    n.className = 'node';
    n.style.left = x + 'px';
    n.style.top  = y + 'px';
    logo.appendChild(n);
  }

  // main grid: junctions ONLY at the ends (outer top & bottom edges).
  // the inner lines that touch the letters get no junctions.
  var main = [];
  logo.querySelectorAll('.cell').forEach(function(c){ if (!c.closest('.tower')) main.push(c); });
  main.forEach(function(c, i){
    var r = c.getBoundingClientRect();
    if (i < 9){                              // top band row -> grid TOP edge
      addNode(r.left, r.top); addNode(r.right, r.top);
    } else if (i >= main.length - 9){        // bottom band row -> grid BOTTOM edge
      addNode(r.left, r.bottom); addNode(r.right, r.bottom);
    }
    // letter row -> no junctions (those lines touch the letters)
  });

  // empty box: junctions at its corners only (the ends), not internal divisions
  logo.querySelectorAll('.tower').forEach(function(t){
    var r = t.getBoundingClientRect();
    addNode(r.left, r.top);    addNode(r.right, r.top);
    addNode(r.left, r.bottom); addNode(r.right, r.bottom);
  });
}

function refresh(){ fitGlyphs(); placeNodes(); }

function run(){
  placeNodes();                 // junctions don't need the font -> place them now
  fitGlyphs();                  // first pass (may use fallback metrics)
  if (document.fonts) {
    var jobs = [];
    if (document.fonts.load)  jobs.push(document.fonts.load(FONT));
    if (document.fonts.ready) jobs.push(document.fonts.ready);
    if (jobs.length) Promise.all(jobs).then(refresh, refresh);   // re-fit with real font
  }
}

run();
window.addEventListener('load', run);
window.addEventListener('resize', function(){ placeNodes(); });

/* ---- preloader: reveal the site only after the hero image (+ fonts) load ---- */
(function(){
  var pre = document.getElementById('preloader');
  if (!pre) return;
  document.documentElement.style.overflow = 'hidden';   // lock scroll while loading
  function reveal(){
    document.documentElement.style.overflow = '';        // unlock
    pre.classList.add('hidden');
    setTimeout(function(){
      var root = document.documentElement;
      root.style.setProperty('--la', 0);            // pin hidden, then fade in
      document.body.classList.remove('loading');    // tower fades in (CSS transition)
      var t0 = null;
      function step(ts){
        if (t0 === null) t0 = ts;
        var k = Math.min((ts - t0) / 700, 1);        // 0 -> 1 over 700ms
        root.style.setProperty('--la', k);
        if (k < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }, 750);
  }
  var jobs = [
    new Promise(function(res){
      var img = new Image();
      img.onload = img.onerror = res;
      img.src = '/home-glydi/bag.jpeg';
    }),
    new Promise(function(res){ setTimeout(res, 1100); })   /* minimum on-screen time */
  ];
  if (document.fonts && document.fonts.ready) jobs.push(document.fonts.ready);
  var safety = new Promise(function(res){ setTimeout(res, 6000); });   /* never hang */
  Promise.race([ Promise.all(jobs), safety ]).then(reveal);
})();

/* ---- pipeline: single-open accordion (opening one closes the others) ---- */
(function(){
  var items = Array.prototype.slice.call(document.querySelectorAll('.pipeline li'));
  if (!items.length) return;
  function setOpen(li, open){
    var detail = li.querySelector('.step-detail');
    var btn = li.querySelector('.step-btn');
    li.classList.toggle('is-open', open);
    if (detail) detail.classList.toggle('open', open);
    if (btn){
      btn.classList.toggle('open', open);
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
  }
  items.forEach(function(li){
    var head = li.querySelector('.step-head');
    var detail = li.querySelector('.step-detail');
    if (!head || !detail) return;
    head.addEventListener('click', function(){
      var willOpen = !detail.classList.contains('open');
      items.forEach(function(other){ if (other !== li) setOpen(other, false); });   /* close the rest */
      setOpen(li, willOpen);                                                          /* toggle this one */
    });
  });
})();

/* ---- scroll: ONROL drifts up + hero image zooms in ---- */
(function(){
  var logo = document.querySelector('.logo');
  var bg = document.querySelector('.hero-bg');
  if (!logo) return;
  var ticking = false;
  function apply(){
    ticking = false;
    var p = window.scrollY / window.innerHeight;       // hero progress 0..1+
    p = p < 0 ? 0 : (p > 1 ? 1 : p);
    // ONROL drifts up on scroll; centered on mobile, sits lower on desktop
    var base = window.innerWidth <= 900 ? 0 : 16;      // resting vertical offset (vh) — centered on mobile
    logo.style.transform = 'translateY(' + (base - p * 55) + 'vh)';
    if (bg) bg.style.transform = 'scale(' + (1 + p * 0.45) + ')';   // hero image zooms in
  }
  window.addEventListener('scroll', function(){
    if (!ticking){ ticking = true; requestAnimationFrame(apply); }
  }, { passive:true });
  window.addEventListener('resize', apply);
  apply();
})();

