/* ---- footer: decoding/scramble effect when it scrolls into view ---- */
(function(){
  var footer = document.querySelector('.footer');
  if (!footer) return;
  var targets = footer.querySelectorAll('h3, h4, .f-tag');
  var CH = '!<>-_\\/[]{}=+*^?#@%$&';

  function decode(el, delay){
    if (el._dec) return;                 // already scrambling -> don't overlap
    el._dec = true;
    var finalText = el.getAttribute('data-text') || el.textContent;
    el.setAttribute('data-text', finalText);
    var queue = [], frame = 0;
    for (var i = 0; i < finalText.length; i++){
      var c = finalText[i];
      if (c === ' '){ queue.push({to:' ', start:0, end:0}); continue; }
      var start = delay + Math.floor(Math.random() * 16);
      var end = start + 14 + Math.floor(Math.random() * 24);
      queue.push({to:c, start:start, end:end, ch:''});
    }
    (function run(){
      var out = '', done = 0;
      for (var i = 0; i < queue.length; i++){
        var q = queue[i];
        if (frame >= q.end){ done++; out += q.to; }
        else if (frame >= q.start){
          if (!q.ch || Math.random() < 0.3) q.ch = CH[Math.floor(Math.random() * CH.length)];
          out += '<span class="dec">' + q.ch + '</span>';
        }
      }
      el.innerHTML = out;
      frame++;
      if (done < queue.length) requestAnimationFrame(run);
      else { el.textContent = finalText; el._dec = false; }
    })();
  }

  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce) return;   // leave footer text as-is, no scramble

  // decode on hover (links + headings)
  footer.querySelectorAll('a, h3, h4, .f-tag').forEach(function(el){
    el.addEventListener('mouseenter', function(){ decode(el, 0); });
  });

  // decode once when the footer scrolls into view
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){
        targets.forEach(function(el, i){ decode(el, i * 5); });
        io.disconnect();
      }
    });
  }, { threshold:0.2 });
  io.observe(footer);
})();

/* ---- section headings: decode/scramble "texting" effect when scrolled into view ---- */
(function(){
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  // plain-text headings only (skip the panel h1 — it has a styled <span>)
  var targets = document.querySelectorAll('.build-title, .who-title, .pipe-title, .who-head .pipe-eyebrow, .panel-right .pipe-eyebrow, .build-text .pipe-eyebrow');
  if (!targets.length || reduce || !('IntersectionObserver' in window)) return;
  var CH = '!<>-_\\/[]{}=+*^?#@%$&';

  function decode(el, delay){
    if (el._dec) return;
    el._dec = true;
    var finalText = el.getAttribute('data-text') || el.textContent;
    el.setAttribute('data-text', finalText);
    var queue = [], frame = 0;
    for (var i = 0; i < finalText.length; i++){
      var c = finalText[i];
      if (c === ' '){ queue.push({to:' ', start:0, end:0}); continue; }
      var start = delay + Math.floor(Math.random() * 16);
      var end = start + 14 + Math.floor(Math.random() * 24);
      queue.push({to:c, start:start, end:end, ch:''});
    }
    (function run(){
      var out = '', done = 0;
      for (var i = 0; i < queue.length; i++){
        var q = queue[i];
        if (frame >= q.end){ done++; out += q.to; }
        else if (frame >= q.start){
          if (!q.ch || Math.random() < 0.3) q.ch = CH[Math.floor(Math.random() * CH.length)];
          out += '<span class="dec">' + q.ch + '</span>';
        }
      }
      el.innerHTML = out;
      frame++;
      if (done < queue.length) requestAnimationFrame(run);
      else { el.textContent = finalText; el._dec = false; }
    })();
  }

  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ decode(e.target, 0); io.unobserve(e.target); }
    });
  }, { threshold:0.35 });
  targets.forEach(function(el){ io.observe(el); });
})();

/* ---- custom video play / mute controls ---- */
(function(){
  var bv = document.querySelector('.build-video');
  var vid = document.getElementById('aboutVid');
  if (!bv || !vid) return;
  var playBtn = document.getElementById('vidPlay');
  var muteBtn = document.getElementById('vidMute');
  var userPaused = false;                       /* true only if the user paused it themselves */
  function play(){ var p = vid.play(); if (p && p.catch) p.catch(function(){}); }
  function toggle(){ if (vid.paused){ userPaused = false; play(); } else { userPaused = true; vid.pause(); } }
  playBtn.addEventListener('click', toggle);
  vid.addEventListener('click', toggle);     // click the video to pause -> big button returns
  vid.addEventListener('play',  function(){ bv.classList.add('is-playing', 'started'); });
  vid.addEventListener('pause', function(){ bv.classList.remove('is-playing'); });
  muteBtn.addEventListener('click', function(){
    vid.muted = !vid.muted;
    bv.classList.toggle('is-muted', vid.muted);
  });

  /* play when the section scrolls into view, pause when it leaves */
  if ('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){ if (!userPaused) play(); }
        else { vid.pause(); }
      });
    }, { threshold:0.35 });
    io.observe(bv);
  } else {
    play();
  }
})();

/* ---- friction-free lead capture (Apply Now) ---- */
(function(){
  var modal = document.getElementById('leadModal');
  if (!modal) return;
  var form = document.getElementById('leadForm');
  var closeBtn = document.getElementById('leadClose');
  var lastFocus = null;
  function open(e){
    if (e) e.preventDefault();
    lastFocus = document.activeElement;
    modal.hidden = false;
    document.documentElement.style.overflow = 'hidden';
    var first = document.getElementById('leadName');
    if (first) first.focus();
  }
  function close(){
    modal.hidden = true;
    document.documentElement.style.overflow = '';
    if (lastFocus) lastFocus.focus();
  }
  document.querySelectorAll('.js-apply').forEach(function(a){
    a.addEventListener('click', open);
  });
  closeBtn.addEventListener('click', close);
  modal.addEventListener('click', function(e){ if (e.target === modal) close(); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape' && !modal.hidden) close(); });
  form.addEventListener('submit', function(e){
    e.preventDefault();
    var name  = document.getElementById('leadName').value.trim();
    var email = document.getElementById('leadEmail').value.trim();
    var phone = document.getElementById('leadPhone').value.trim();
    if (!name || !email || !phone) return;
    const url = generateWhatsAppLink({ name, email, phone });
    if (url) {
      window.open(url, '_blank', 'noopener,noreferrer');
      close();
    }
    form.reset();
  });
})();

