/* scroll-reveal: fade + rise sections as they enter the viewport */
(function(){
  var els = document.querySelectorAll('.reveal');
  if (!els.length) return;
  var noMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (noMotion || !('IntersectionObserver' in window)){
    els.forEach(function(el){ el.classList.add('in'); });   // show immediately
    return;
  }
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, { threshold:0.12, rootMargin:'0px 0px -8% 0px' });
  els.forEach(function(el){ io.observe(el); });
})();

/* ---- logo colour adapts to the section behind it (white on dark, orange on light) ---- */
(function(){
  var logo = document.querySelector('.site-logo');
  var navEl = document.querySelector('.nav');
  if (!logo || !('IntersectionObserver' in window)) return;
  var darks = [];
  ['.hero'].forEach(function(sel){                 /* only the hero is dark now */
    var el = document.querySelector(sel);
    if (el) darks.push(el);
  });
  if (!darks.length) return;
  var active = new Set();
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting) active.add(e.target); else active.delete(e.target);
    });
    var over = active.size > 0;
    logo.classList.toggle('on-dark', over);         /* logo white over hero, orange elsewhere */
    if (navEl) navEl.classList.toggle('on-dark', over);   /* nav links white over hero */
  }, { rootMargin:'-44px 0px -92% 0px', threshold:0 });   /* thin detection band at the logo's height */
  darks.forEach(function(el){ io.observe(el); });
})();

/* ---- scroll-progress bar ---- */
(function(){
  var bar = document.getElementById('scrollProgress');
  if (!bar) return;
  var ticking = false;
  function update(){
    ticking = false;
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    var pct = max > 0 ? (h.scrollTop || window.pageYOffset) / max * 100 : 0;
    bar.style.width = pct + '%';
  }
  window.addEventListener('scroll', function(){ if (!ticking){ ticking = true; requestAnimationFrame(update); } }, { passive:true });
  window.addEventListener('resize', update);
  update();
})();

/* ---- nav: hide on scroll down, show on scroll up ---- */
(function(){
  var nav = document.querySelector('.nav');
  if (!nav) return;
  var last = window.pageYOffset || 0, ticking = false;
  function onScroll(){
    ticking = false;
    var y = window.pageYOffset || document.documentElement.scrollTop || 0;
    if (nav.classList.contains('open')){ document.body.classList.remove('nav-up'); last = y; return; }  /* keep visible when mobile menu is open */
    if (y > last && y > 140){ document.body.classList.add('nav-up'); }     /* scrolling down */
    else { document.body.classList.remove('nav-up'); }                     /* scrolling up */
    last = y < 0 ? 0 : y;
  }
  window.addEventListener('scroll', function(){ if (!ticking){ ticking = true; requestAnimationFrame(onScroll); } }, { passive:true });
})();

/* ---- WHO showcase: one feature card + tab strip + autoplay ---- */
(function(){
  var data = document.getElementById('wsData');
  if (!data) return;
  var items = Array.prototype.slice.call(data.querySelectorAll('.ws-item')).map(function(el){
    return {
      num:  el.getAttribute('data-num'),
      img:  el.getAttribute('data-img'),
      svg:  el.querySelector('.ws-svg').innerHTML,
      name: el.querySelector('h4').textContent,
      tag:  el.querySelector('.ws-tag').textContent,
      desc: el.querySelector('p').textContent
    };
  });
  var n = items.length, index = 0;

  var card   = document.getElementById('wsCard');
  var media  = document.getElementById('wsMedia');
  var count  = document.getElementById('wsCount');
  var chip   = document.getElementById('wsChip');
  var tagEl  = document.getElementById('wsTag');
  var title  = document.getElementById('wsTitle');
  var desc   = document.getElementById('wsDesc');
  var tabsWrap = document.getElementById('wsTabs');
  var prevBtn = document.getElementById('wsPrev');
  var nextBtn = document.getElementById('wsNext');

  function mod(i){ return (i % n + n) % n; }

  /* preload every image so swaps never flash */
  items.forEach(function(it){ var im = new Image(); im.src = it.img; });

  /* build the number-tab strip */
  var tabs = items.map(function(it, i){
    var b = document.createElement('button');
    b.className = 'ws-tab'; b.type = 'button';
    b.textContent = it.num; b.title = it.name;
    b.setAttribute('aria-label', it.name);
    b.addEventListener('click', function(){ go(i); });
    tabsWrap.appendChild(b);
    return b;
  });

  function fill(){
    var it = items[index];
    media.style.backgroundImage = "url('" + it.img + "')";
    count.textContent = it.num + ' / ' + n;
    chip.innerHTML = it.svg;
    tagEl.textContent = it.tag;
    title.textContent = it.name;
    desc.textContent = it.desc;
    tabs.forEach(function(b, i){ b.classList.toggle('is-on', i === index); });
  }

  /* cross-fade the card while content swaps */
  function render(){
    card.classList.add('is-swapping');
    window.setTimeout(function(){ fill(); card.classList.remove('is-swapping'); }, 200);
  }

  function go(i){ index = mod(i); render(); start(); }   /* manual nav resets the clock */

  /* ---- autoplay (every 2s) — always running; manual nav just resets the clock ---- */
  var AUTO = 2000, timer = null;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  function start(){ stop(); if (reduce || document.hidden) return; timer = setInterval(function(){ index = mod(index + 1); render(); }, AUTO); }
  function stop(){ if (timer){ clearInterval(timer); timer = null; } }

  if (prevBtn) prevBtn.addEventListener('click', function(){ go(index - 1); });
  if (nextBtn) nextBtn.addEventListener('click', function(){ go(index + 1); });

  /* pause only when the tab is hidden (keeps auto-advancing otherwise) */
  document.addEventListener('visibilitychange', function(){ if (document.hidden) stop(); else start(); });

  /* swipe on the card */
  var startX = null;
  card.addEventListener('touchstart', function(e){ startX = e.touches[0].clientX; stop(); }, { passive:true });
  card.addEventListener('touchend', function(e){
    if (startX === null) return;
    var dx = e.changedTouches[0].clientX - startX;
    if (Math.abs(dx) > 45){ go(index + (dx < 0 ? 1 : -1)); } else { start(); }
    startX = null;
  }, { passive:true });

  fill();   /* initial paint (no fade) */
  start();
})();
